<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireAdmin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');$db->beginTransaction();try{$st=$db->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$st->execute(array('cafe_name',trim($_POST['cafe_name'])));$st->execute(array('currency',trim($_POST['currency'])));foreach(isset($_POST['tier_name'])?$_POST['tier_name']:array() as $id=>$name){$db->prepare('UPDATE customer_tiers SET name=?,discount_percent=?,first_order_points=?,order_threshold=?,threshold_points=?,point_value=? WHERE id=?')->execute(array(trim($name),(float)$_POST['discount'][$id],(int)$_POST['first_points'][$id],(int)$_POST['threshold'][$id],(int)$_POST['bonus_points'][$id],(float)$_POST['point_value'][$id],(int)$id));}$db->commit();Helper::flash('تم حفظ الإعدادات. ملاحظة: تغيير العملة يحتاج تحديث config/config.php.','success');}catch(Exception $e){$db->rollBack();Helper::flash('تعذر حفظ الإعدادات.','danger');}Helper::redirect('modules/settings/index.php');}$settings=$db->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);$tiers=$db->query('SELECT * FROM customer_tiers ORDER BY id')->fetchAll();$pageTitle='الإعدادات';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>إعدادات النظام</h1><p>معلومات المقهى وقواعد برنامج الولاء</p></div></div><form method="post"><?= Helper::csrfField() ?><div class="card mb-3"><div class="card-header">الإعدادات العامة</div><div class="card-body row g-3"><div class="col-md-6"><label class="form-label">اسم المقهى</label><input class="form-control" name="cafe_name" value="<?= Helper::e(isset($settings['cafe_name'])?$settings['cafe_name']:APP_NAME) ?>"></div><div class="col-md-6"><label class="form-label">رمز العملة</label><input class="form-control" name="currency" value="<?= Helper::e(isset($settings['currency'])?$settings['currency']:APP_CURRENCY) ?>"></div></div></div><div class="card mb-3"><div class="card-header">طبقات الولاء — النقاط المكتسبة عند كل طلبية حسب العتبة</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>الطبقة</th><th>خصم %</th><th>نقاط أول طلبية يومياً</th><th>عدد الطلبات للعتبة</th><th>نقاط المكافأة</th><th>قيمة النقطة</th></tr></thead><tbody><?php foreach($tiers as $t): ?><tr><td><input class="form-control" name="tier_name[<?= (int)$t['id'] ?>]" value="<?= Helper::e($t['name']) ?>"></td><td><input class="form-control" type="number" step=".01" name="discount[<?= (int)$t['id'] ?>]" value="<?= Helper::e($t['discount_percent']) ?>"></td><td><input class="form-control" type="number" name="first_points[<?= (int)$t['id'] ?>]" value="<?= (int)$t['first_order_points'] ?>"></td><td><input class="form-control" type="number" name="threshold[<?= (int)$t['id'] ?>]" value="<?= (int)$t['order_threshold'] ?>"></td><td><input class="form-control" type="number" name="bonus_points[<?= (int)$t['id'] ?>]" value="<?= (int)$t['threshold_points'] ?>"></td><td><input class="form-control" type="number" step=".01" name="point_value[<?= (int)$t['id'] ?>]" value="<?= Helper::e($t['point_value']) ?>"></td></tr><?php endforeach; ?></tbody></table></div></div><button class="btn btn-coffee">حفظ الإعدادات</button></form><?php require APP_ROOT.'/includes/footer.php';
